import 'package:firebase_auth/firebase_auth.dart'; import 'package:flutter/material.dart';
import '../../../services/stay/stay_service.dart'; import '../../messenger/presentation/messenger_screen.dart';
class AurenStayScreen extends StatefulWidget{const AurenStayScreen({super.key});@override State<AurenStayScreen> createState()=>_AurenStayScreenState();}
class _AurenStayScreenState extends State<AurenStayScreen>{String city='',country='';
void search(){final c=TextEditingController(text:city),co=TextEditingController(text:country);showDialog(context:context,builder:(ctx)=>AlertDialog(title:const Text('ابحث عن إقامة'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:c,decoration:const InputDecoration(labelText:'المدينة')),TextField(controller:co,decoration:const InputDecoration(labelText:'الدولة'))]),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('إلغاء')),FilledButton(onPressed:(){setState((){city=c.text;country=co.text;});Navigator.pop(ctx);},child:const Text('بحث'))]));}
@override Widget build(BuildContext context){final uid=FirebaseAuth.instance.currentUser?.uid;return Scaffold(appBar:AppBar(title:const Text('Hotels • Stay • Packages'),actions:[IconButton(icon:const Icon(Icons.auto_awesome),onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const MessengerScreen(initialPrompt:'ساعدني أجد إقامة مناسبة حسب الوجهة والميزانية والتواريخ وعدد المسافرين، وقارن الخيارات بوضوح.'))))]),body:uid==null?const Center(child:Text('سجّل الدخول لاستخدام الإقامة.')):Column(children:[Padding(padding:const EdgeInsets.all(12),child:Row(children:[Expanded(child:Text(city.isEmpty&&country.isEmpty?'كل الإقامات':city+', '+country)),IconButton(onPressed:search,icon:const Icon(Icons.tune))])),Expanded(child:StreamBuilder<List<AurenStay>>(stream:AurenStayService.instance.watch(city:city,country:country),builder:(context,s){if(s.hasError)return const Center(child:Text('تعذر تحميل الإقامات.'));if(!s.hasData)return const Center(child:CircularProgressIndicator());if(s.data!.isEmpty)return const Center(child:Text('لا توجد إقامات مطابقة حالياً. جرّب مدينة أو دولة أخرى.'));return ListView.separated(padding:const EdgeInsets.all(12),itemCount:s.data!.length,separatorBuilder:(_,__)=>const SizedBox(height:10),itemBuilder:(context,i){final x=s.data![i];return Card(child:ListTile(title:Text(x.name),subtitle:Text('${x.type} • ${x.city}, ${x.country}\n${x.priceMinor} ${x.currency}/ليلة • حتى ${x.guests} ضيف'),isThreeLine:true,trailing:const Icon(Icons.chevron_right),onTap:()=>_book(x,uid));});}))]) );}
Future<void> _book(AurenStay stay,String uid)async{DateTime? a,b;int guests=1;await showDialog(context:context,builder:(ctx)=>StatefulBuilder(builder:(ctx,setState)=>AlertDialog(title:Text('طلب حجز • ${stay.name}'),content:Column(mainAxisSize:MainAxisSize.min,children:[OutlinedButton(onPressed:()async{final d=await showDatePicker(context:ctx,firstDate:DateTime.now(),lastDate:DateTime.now().add(const Duration(days:3650)),initialDate:DateTime.now());if(d!=null)setState(()=>a=d);},child:Text(a==null?'تاريخ الوصول':'${a!.day}/${a!.month}/${a!.year}')),OutlinedButton(onPressed:()async{final d=await showDatePicker(context:ctx,firstDate:a??DateTime.now(),lastDate:DateTime.now().add(const Duration(days:3650)),initialDate:a??DateTime.now());if(d!=null)setState(()=>b=d);},child:Text(b==null?'تاريخ المغادرة':'${b!.day}/${b!.month}/${b!.year}')),TextField(keyboardType:TextInputType.number,onChanged:(v)=>guests=int.tryParse(v)??1,decoration:const InputDecoration(labelText:'الضيوف'))]),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('إلغاء')),FilledButton(onPressed:()async{if(a==null||b==null)return;try{await AurenStayService.instance.createBooking(uid:uid,stay:stay,checkIn:a!,checkOut:b!,guests:guests);if(ctx.mounted){Navigator.pop(ctx);ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('تم إرسال طلب الحجز.')));}}catch(e){if(ctx.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}},child:const Text('إرسال الطلب'))])));}
}